import{_ as t,c as s,o as i,j as n,Y as r,t as o}from"./chunks/framework.D-NV0Bun.js";const b=JSON.parse('{"title":"glob | x-cmd man (man7) | globbing pathnames","titleTemplate":false,"description":"x-cmd man (man7 Manual Page) | glob - globbing pathnames","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"glob | x-cmd man (man7) | globbing pathnames"}],["meta",{"name":"og:description","content":"x-cmd man (man7 Manual Page) | glob - globbing pathnames"}]]},"headers":[],"params":{"isMan":true,"man":"glob","category":"man7","desc":"globbing pathnames"},"relativePath":"man7/glob.md","filePath":"man7/[man].md"}'),h={name:"man7/glob.md"},l={class:"visually-hidden"};function c(a,e,p,d,m,g){return i(),s("div",null,[n("h1",l,o(a.$params.man),1),e[0]||(e[0]=r('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>glob - globbing pathnames</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Long ago, in UNIX V6, there was a program <em>/etc/glob</em> that would expand wildcard patterns. Soon afterward this became a shell built-in.</p><p>These days there is also a library routine <strong>glob</strong>(3) that will perform this function for a user program.</p><p>The rules are as follows (POSIX.2, 3.13).</p><h3 id="wildcard-matching" tabindex="-1">Wildcard matching <a class="header-anchor" href="#wildcard-matching" aria-label="Permalink to &quot;Wildcard matching&quot;">​</a></h3><p>A string is a wildcard pattern if it contains one of the characters &#39;?&#39;, &#39;*&#39;, or &#39;[&#39;. Globbing is the operation that expands a wildcard pattern into the list of pathnames matching the pattern. Matching is defined by:</p><p>A &#39;?&#39; (not between brackets) matches any single character.</p><p>A &#39;*&#39; (not between brackets) matches any string, including the empty string.</p><p><strong>Character classes</strong></p><p>An expression &quot;<em>[...]</em>&quot; where the first character after the leading &#39;[&#39; is not an &#39;!&#39; matches a single character, namely any of the characters enclosed by the brackets. The string enclosed by the brackets cannot be empty; therefore &#39;]&#39; can be allowed between the brackets, provided that it is the first character. (Thus, &quot;<em>[][!]</em>&quot; matches the three characters &#39;[&#39;, &#39;]&#39;, and &#39;!&#39;.)</p><p><strong>Ranges</strong></p><p>There is one special convention: two characters separated by &#39;-&#39; denote a range. (Thus, &quot;<em>[A-Fa-f0-9]</em>&quot; is equivalent to &quot;<em>[ABCDEFabcdef0123456789]</em>&quot;.) One may include &#39;-&#39; in its literal meaning by making it the first or last character between the brackets. (Thus, &quot;<em>[]-]</em>&quot; matches just the two characters &#39;]&#39; and &#39;-&#39;, and &quot;<em>[--0]</em>&quot; matches the three characters &#39;-&#39;, &#39;.&#39;, and &#39;0&#39;, since &#39;/&#39; cannot be matched.)</p><p><strong>Complementation</strong></p><p>An expression &quot;<em>[!...]</em>&quot; matches a single character, namely any character that is not matched by the expression obtained by removing the first &#39;!&#39; from it. (Thus, &quot;<em>[!]a-]</em>&quot; matches any single character except &#39;]&#39;, &#39;a&#39;, and &#39;-&#39;.)</p><p>One can remove the special meaning of &#39;?&#39;, &#39;*&#39;, and &#39;[&#39; by preceding them by a backslash, or, in case this is part of a shell command line, enclosing them in quotes. Between brackets these characters stand for themselves. Thus, &quot;<em>[[?*\\]</em>&quot; matches the four characters &#39;[&#39;, &#39;?&#39;, &#39;*&#39;, and &#39;\\&#39;.</p><h3 id="pathnames" tabindex="-1">Pathnames <a class="header-anchor" href="#pathnames" aria-label="Permalink to &quot;Pathnames&quot;">​</a></h3><p>Globbing is applied on each of the components of a pathname separately. A &#39;/&#39; in a pathname cannot be matched by a &#39;?&#39; or &#39;*&#39; wildcard, or by a range like &quot;<em>[.-0]</em>&quot;. A range containing an explicit &#39;/&#39; character is syntactically incorrect. (POSIX requires that syntactically incorrect patterns are left unchanged.)</p><p>If a filename starts with a &#39;.&#39;, this character must be matched explicitly. (Thus, <em>rm *</em> will not remove .profile, and <em>tar c *</em> will not archive all your files; <em>tar c .</em> is better.)</p><h3 id="empty-lists" tabindex="-1">Empty lists <a class="header-anchor" href="#empty-lists" aria-label="Permalink to &quot;Empty lists&quot;">​</a></h3><p>The nice and simple rule given above: &quot;expand a wildcard pattern into the list of matching pathnames&quot; was the original UNIX definition. It allowed one to have patterns that expand into an empty list, as in</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -wait</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.gif</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.jpg</span></span></code></pre></div><p>where perhaps no *.gif files are present (and this is not an error). However, POSIX requires that a wildcard pattern is left unchanged when it is syntactically incorrect, or the list of matching pathnames is empty. With <em>bash</em> one can force the classical behavior using this command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shopt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nullglob</span></span></code></pre></div><p>(Similar problems occur elsewhere. For example, where old scripts have</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> . </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;*~&quot;`</span></span></code></pre></div><p>new scripts require</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nosuchfile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> . </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;*~&quot;`</span></span></code></pre></div><p>to avoid error messages from <em>rm</em> called with an empty argument list.)</p><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><h3 id="regular-expressions" tabindex="-1">Regular expressions <a class="header-anchor" href="#regular-expressions" aria-label="Permalink to &quot;Regular expressions&quot;">​</a></h3><p>Note that wildcard patterns are not regular expressions, although they are a bit similar. First of all, they match filenames, rather than text, and secondly, the conventions are not the same: for example, in a regular expression &#39;*&#39; means zero or more copies of the preceding thing.</p><p>Now that regular expressions have bracket expressions where the negation is indicated by a &#39;^&#39;, POSIX has declared the effect of a wildcard pattern &quot;<em>[^...]</em>&quot; to be undefined.</p><h3 id="character-classes-and-internationalization" tabindex="-1">Character classes and internationalization <a class="header-anchor" href="#character-classes-and-internationalization" aria-label="Permalink to &quot;Character classes and internationalization&quot;">​</a></h3><p>Of course ranges were originally meant to be ASCII ranges, so that &quot;<em>[ -%]</em>&quot; stands for &quot;<em>[ !&quot;#$%]</em>&quot; and &quot;<em>[a-z]</em>&quot; stands for &quot;any lowercase letter&quot;. Some UNIX implementations generalized this so that a range X-Y stands for the set of characters with code between the codes for X and for Y. However, this requires the user to know the character coding in use on the local system, and moreover, is not convenient if the collating sequence for the local alphabet differs from the ordering of the character codes. Therefore, POSIX extended the bracket notation greatly, both for wildcard patterns and for regular expressions. In the above we saw three types of items that can occur in a bracket expression: namely (i) the negation, (ii) explicit single characters, and (iii) ranges. POSIX specifies ranges in an internationally more useful way and adds three more types:</p><p>(iii) Ranges X-Y comprise all characters that fall between X and Y (inclusive) in the current collating sequence as defined by the <strong>LC_COLLATE</strong> category in the current locale.</p><p>(iv) Named character classes, like</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[:alnum:]  [:alpha:]  [:blank:]  [:cntrl:]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[:digit:]  [:graph:]  [:lower:]  [:print:]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[:punct:]  [:space:]  [:upper:]  [:xdigit:]</span></span></code></pre></div><p>so that one can say &quot;<em>[[:lower:]]</em>&quot; instead of &quot;<em>[a-z]</em>&quot;, and have things work in Denmark, too, where there are three letters past &#39;z&#39; in the alphabet. These character classes are defined by the <strong>LC_CTYPE</strong> category in the current locale.</p><p>(v) Collating symbols, like &quot;<em>[.ch.]</em>&quot; or &quot;<em>[.a-acute.]</em>&quot;, where the string between &quot;<em>[.</em>&quot; and &quot;<em>.]</em>&quot; is a collating element defined for the current locale. Note that this may be a multicharacter element.</p><p>(vi) Equivalence class expressions, like &quot;<em>[=a=]</em>&quot;, where the string between &quot;<em>[=</em>&quot; and &quot;<em>=]</em>&quot; is any collating element from its equivalence class, as defined for the current locale. For example, &quot;<em>[[=a=]]</em>&quot; might be equivalent to &quot;<em>[aáàäâ]</em>&quot;, that is, to &quot;<em>[a[.a-acute.][.a-grave.][.a-umlaut.][.a-circumflex.]]</em>&quot;.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>sh</strong>(1), <strong>fnmatch</strong>(3), <strong>glob</strong>(3), <strong>locale</strong>(7), <strong>regex</strong>(7)</p>',44))])}const k=t(h,[["render",c]]);export{b as __pageData,k as default};
